package com.fitpal.app.ui.theme

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager

/**
 * Switches the launcher icon. Every icon is an `<activity-alias>` of [com.fitpal.app.FitPalActivity]
 * (generated by tools/gen_app_icons.py) and exactly one is enabled; switching enables the new one
 * first, then disables the rest, without killing the app. The launcher redraws on its own schedule
 * (a few seconds), and some launchers — Samsung's included — drop the old home-screen shortcut, so
 * the picker says so before switching.
 */
object AppIconSwitcher {

    fun current(context: Context): AppIcon {
        val pm = context.packageManager
        return AppIconCatalog.all.firstOrNull { isEnabled(pm, context, it) } ?: AppIconCatalog.byId(AppIconCatalog.DEFAULT_ID)!!
    }

    fun apply(context: Context, icon: AppIcon) {
        val pm = context.packageManager
        pm.setComponentEnabledSetting(component(context, icon), PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
        AppIconCatalog.all.filter { it.id != icon.id && isEnabled(pm, context, it) }.forEach {
            pm.setComponentEnabledSetting(component(context, it), PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
        }
    }

    /** The look hint of [look] — matched against [AppIcon.lookHint] for "matches your look". */
    fun lookHint(look: Look): String = when (look.style) {
        LookStyle.GLOW -> "GLOW:${look.appearance.palette.name}"
        LookStyle.LIQUID -> if (look.isLight) "LIQUID:LIGHT" else "LIQUID:DARK"
        LookStyle.PAPER -> if (look.isLight) "PAPER:LIGHT" else "PAPER:DARK"
        LookStyle.MATERIAL -> if (look.isLight) "MATERIAL:LIGHT" else "MATERIAL:DARK"
    }

    /** The icon in the same motif as [icon], drawn for [look] — null for the fun ones or if it already matches. */
    fun matchFor(icon: AppIcon, look: Look): AppIcon? {
        if (icon.group == "fun") return null
        val hint = lookHint(look)
        if (icon.lookHint == hint) return null
        return AppIconCatalog.all.firstOrNull { it.group == icon.group && it.lookHint == hint }
    }

    private fun component(context: Context, icon: AppIcon) = ComponentName(context.packageName, icon.alias)

    private fun isEnabled(pm: PackageManager, context: Context, icon: AppIcon): Boolean =
        when (pm.getComponentEnabledSetting(component(context, icon))) {
            PackageManager.COMPONENT_ENABLED_STATE_ENABLED -> true
            PackageManager.COMPONENT_ENABLED_STATE_DISABLED -> false
            // Never switched: the manifest decides — only the original icon starts enabled.
            else -> icon.id == AppIconCatalog.DEFAULT_ID
        }
}
